package at.redeye.twelvelittlescoutsclerk;

import at.redeye.FrameWork.base.Root;
import at.redeye.FrameWork.base.transaction.Transaction;
import at.redeye.twelvelittlescoutsclerk.bindtypes.DBBill;
import java.util.List;
import org.apache.log4j.Logger;

/**
 * Startup job which computes and stores the SHA-256 checksums of all bills
 * which have no checksum yet (bills uploaded/generated before the
 * {@code BILLS.checksum} column existed).
 *
 * <p>The job runs in a background thread with its own database transaction so
 * the user interface is not blocked. It runs once after the application has
 * started; afterwards no bill without checksum remains.</p>
 */
public class BillChecksumWorker implements Runnable {

    private static final Logger logger = Logger.getLogger(BillChecksumWorker.class.getName());

    /** Wait before starting, so the UI is up and the database migration is done. */
    private static final long STARTUP_DELAY_MS = 2_500;

    /** Commit after this many updated bills. */
    private static final int COMMIT_INTERVAL = 25;

    private final Root root;

    public BillChecksumWorker(Root root) {
        this.root = root;
    }

    @Override
    public void run() {
        try {
            Thread.sleep(STARTUP_DELAY_MS);
        } catch (InterruptedException ex) {
            Thread.currentThread().interrupt();
            return;
        }

        Transaction trans = null;
        boolean ownTransaction = false;

        try {
            trans = root.getDBConnection().getNewTransaction();

            if (trans == null || !trans.isOpen()) {
                logger.warn("BillChecksumWorker: no database transaction available");
                return;
            }

            // some backends (e.g. SQLite) return the shared default transaction,
            // which must not be closed by this worker
            ownTransaction = trans != root.getDBConnection().getDefaultTransaction();

            int updated = updateMissingChecksums(trans);

            if (updated > 0) {
                logger.info("BillChecksumWorker: checksum computed for " + updated + " bill(s)");
            } else {
                logger.info("BillChecksumWorker: all bills have a checksum already");
            }
        } catch (InterruptedException ex) {
            Thread.currentThread().interrupt();
        } catch (Exception ex) {
            logger.error("BillChecksumWorker failed", ex);
            rollback(trans);
        } finally {
            closeTransaction(trans, ownTransaction);
        }
    }

    /**
     * Computes the checksums of all bills without checksum (all billing periods).
     *
     * @return the number of updated bills
     */
    private int updateMissingChecksums(Transaction trans) throws Exception {

        List<DBBill> missing = BillChecksumHelper.fetchBillsWithoutChecksum(trans, null);

        if (missing.isEmpty()) {
            return 0;
        }

        logger.info("BillChecksumWorker: " + missing.size() + " bill(s) without checksum");

        int updated = 0;
        int uncommitted = 0;

        for (DBBill entry : missing) {
            if (Thread.currentThread().isInterrupted()) {
                throw new InterruptedException();
            }

            // load one bill at a time, so only one document blob is in memory
            DBBill bill = BillChecksumHelper.loadBill(trans, entry.idx.getValue());

            if (bill == null) {
                continue;
            }

            if (BillChecksumHelper.updateChecksum(trans, bill, root.getUserName())) {
                updated++;
                uncommitted++;

                if (uncommitted >= COMMIT_INTERVAL) {
                    trans.commit();
                    uncommitted = 0;
                }
            }
        }

        trans.commit();

        return updated;
    }

    private void rollback(Transaction trans) {
        if (trans == null) {
            return;
        }
        try {
            trans.rollback();
        } catch (Exception ex) {
            logger.warn("BillChecksumWorker: rollback failed", ex);
        }
    }

    private void closeTransaction(Transaction trans, boolean ownTransaction) {
        if (trans == null || !ownTransaction) {
            return;
        }
        try {
            if (!root.getDBConnection().closeTransaction(trans)) {
                trans.close();
            }
        } catch (Exception ex) {
            logger.warn("BillChecksumWorker: closing transaction failed", ex);
        }
    }
}
